#include "al_default_repo.h"
namespace al {
Repo importLevelgen(const std::string& bytes){if(bytes.empty()||bytes.size()>8*1024*1024)throw std::runtime_error("missing or oversized legacy library");std::istringstream in(bytes);std::string magic;int version=0,seed,ceilings,lights,player,connected;double cell,height,door;in>>magic>>version;if(magic!="REYOND_WFC"||version!=1)throw std::runtime_error("unknown levelgen library format");if(!(in>>seed>>cell>>height>>door>>ceilings>>lights>>player>>connected))throw std::runtime_error("incomplete levelgen settings");double ignored;for(int i=0;i<3+3+3+6;i++)in>>ignored;size_t count=0;in>>count;if(count<1||count>64)throw std::runtime_error("invalid legacy block count");Repo r;r.uid="legacy";r.name="Imported levelgen library";r.useFilling=false;r.cellSize={cell,cell,height};r.groups=r.weightGroups={"Rooms"};for(size_t i=0;i<count;i++){std::string name,source;float weight;int group,rotations,kind;Int3 footprint;std::array<int,6> sides{};if(!(in>>std::quoted(name)>>weight>>group>>rotations>>kind>>footprint.x>>footprint.y>>footprint.z))throw std::runtime_error("invalid legacy module");for(auto& id:sides)in>>id;if(!(in>>std::quoted(source)))throw std::runtime_error("invalid legacy geometry");std::string uid="legacy_"+std::to_string(i);Geometry g;if(!source.empty()){std::istringstream old(source);std::string header;Vec3 lo,hi;if(!(old>>header>>lo.x>>lo.y>>lo.z>>hi.x>>hi.y>>hi.z)||header!="BOUNDS")throw std::runtime_error("invalid legacy capture bounds");std::string rest((std::istreambuf_iterator<char>(old)),{});g=translateGeometry(parseMap(rest),lo*-1);}else if(kind==1)g.brushes.push_back(box({},r.cellSize,"fb_grey"));else if(kind==0){std::array<bool,6> walls{},doors{};int mapping[6]={3,5,0,2,4,1};for(int d=0;d<4;d++){walls[mapping[d]]=true;doors[mapping[d]]=sides[d]!=0;}g=rescaleGeometry(roomCell(walls,doors,true,ceilings),{cell/256,cell/256,height/192});}
 int mapping[6]={3,5,0,2,4,1};if(volume(footprint)>1){auto big=bigFromGeometry(r,g,footprint,uid,name,"Rooms",weight);if(!rotations)big.actionsGroups.clear();for(size_t c=0;c<big.data.size();c++){auto p=position(c,footprint);auto v=variant(r,big.data[c][0]);for(int d=0;d<6;d++)if(!inside(p+delta[mapping[d]],footprint))v->sideIds[mapping[d]]=std::max(0,sides[d]);}r.bigBlocks.push_back(big);}else{BlockAsset b;b.uid=uid;b.name=name;b.group=b.weightGroup=group==1?"Solid":group==2?"Empty":"Rooms";b.geometry=writeMap(g);b.variants[0].weight=weight;for(int d=0;d<6;d++)b.variants[0].sideIds[mapping[d]]=std::max(0,sides[d]);if(rotations)b.actionsGroups={"Full Rotate On Z"};r.blocks.push_back(b);}}
 integrity(r);return r;}
}
